INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-nioite-1', 'sent-ex-nioite-1', 'en', 'The meeting was held at the university.', 'authored'),
  ('st-ex-nioite-2', 'sent-ex-nioite-2', 'en', 'In Japan, education matters.', 'authored'),
  ('st-ex-nioite-3', 'sent-ex-nioite-3', 'en', 'In that field, he is well known.', 'authored'),
  ('st-ex-nioite-4', 'sent-ex-nioite-4', 'en', 'In modern society, information matters.', 'authored'),
  ('st-ex-wotsuujite-1', 'sent-ex-wotsuujite-1', 'en', 'I came to know him through a friend.', 'authored'),
  ('st-ex-wotsuujite-2', 'sent-ex-wotsuujite-2', 'en', 'You get to know the world through television.', 'authored'),
  ('st-ex-wotsuujite-3', 'sent-ex-wotsuujite-3', 'en', 'I gather information through the newspapers.', 'authored'),
  ('st-ex-wotsuujite-4', 'sent-ex-wotsuujite-4', 'en', 'I learned it through experience.', 'authored'),
  ('st-ex-yueni-1', 'sent-ex-yueni-1', 'en', 'He failed because he was young.', 'authored'),
  ('st-ex-yueni-2', 'sent-ex-yueni-2', 'en', 'Because they were poor, he could not go to school.', 'authored'),
  ('st-ex-yueni-3', 'sent-ex-yueni-3', 'en', 'Having no experience, I hesitated.', 'authored'),
  ('st-ex-yueni-4', 'sent-ex-yueni-4', 'en', 'Because of illness, he left his job.', 'authored'),
  ('st-ex-tote-1', 'sent-ex-tote-1', 'en', 'Even a child is not excused.', 'authored'),
  ('st-ex-tote-2', 'sent-ex-tote-2', 'en', 'I feel exactly the same way.', 'authored'),
  ('st-ex-tote-3', 'sent-ex-tote-3', 'en', 'Even a teacher makes mistakes.', 'authored'),
  ('st-ex-tote-4', 'sent-ex-tote-4', 'en', 'It is not too late even now.', 'authored'),
  ('st-ex-yorihokanai-1', 'sent-ex-yorihokanai-1', 'en', 'There is nothing for it but to give up.', 'authored'),
  ('st-ex-yorihokanai-2', 'sent-ex-yorihokanai-2', 'en', 'There is nothing for it but to do it myself.', 'authored'),
  ('st-ex-yorihokanai-3', 'sent-ex-yorihokanai-3', 'en', 'There is nothing for it but to wait.', 'authored'),
  ('st-ex-yorihokanai-4', 'sent-ex-yorihokanai-4', 'en', 'There is nothing for it but to ask him.', 'authored'),
  ('st-ex-dounimo-1', 'sent-ex-dounimo-1', 'en', 'I simply cannot stand it.', 'authored'),
  ('st-ex-dounimo-2', 'sent-ex-dounimo-2', 'en', 'I simply cannot get to sleep.', 'authored'),
  ('st-ex-dounimo-3', 'sent-ex-dounimo-3', 'en', 'I simply cannot make it out.', 'authored'),
  ('st-ex-dounimo-4', 'sent-ex-dounimo-4', 'en', 'There is nothing to be done about it.', 'authored'),
  ('st-ex-nishiro-1', 'sent-ex-nishiro-1', 'en', 'Whether you are going or not, please let me know.', 'authored'),
  ('st-ex-nishiro-2', 'sent-ex-nishiro-2', 'en', 'Rain or snow, the match is on.', 'authored'),
  ('st-ex-nishiro-3', 'sent-ex-nishiro-3', 'en', 'Student or teacher, the rules are the same.', 'authored'),
  ('st-ex-nishiro-4', 'sent-ex-nishiro-4', 'en', 'Whether you agree or object, say what you think.', 'authored'),
  ('st-ex-hitotsude-1', 'sent-ex-hitotsude-1', 'en', 'A single thought can change a life.', 'authored'),
  ('st-ex-hitotsude-2', 'sent-ex-hitotsude-2', 'en', 'A single word changes the impression.', 'authored'),
  ('st-ex-hitotsude-3', 'sent-ex-hitotsude-3', 'en', 'He has lived on his own two hands.', 'authored'),
  ('st-ex-hitotsude-4', 'sent-ex-hitotsude-4', 'en', 'A change of heart changes the result.', 'authored'),
  ('st-ex-gayueni-1', 'sent-ex-gayueni-1', 'en', 'Being young, he makes plenty of mistakes.', 'authored'),
  ('st-ex-gayueni-2', 'sent-ex-gayueni-2', 'en', 'Precisely because he is famous, he has no freedom.', 'authored'),
  ('st-ex-gayueni-3', 'sent-ex-gayueni-3', 'en', 'It is precisely because he is so conscientious that he is worn out.', 'authored'),
  ('st-ex-gayueni-4', 'sent-ex-gayueni-4', 'en', 'It was precisely for want of experience that it went wrong.', 'authored'),
  ('st-ex-shimatsuda-1', 'sent-ex-shimatsuda-1', 'en', 'Not only was he late, he did not even apologise.', 'authored'),
  ('st-ex-shimatsuda-2', 'sent-ex-shimatsuda-2', 'en', 'In the end he was reduced to tears.', 'authored'),
  ('st-ex-shimatsuda-3', 'sent-ex-shimatsuda-3', 'en', 'He was warned and still would not listen.', 'authored'),
  ('st-ex-shimatsuda-4', 'sent-ex-shimatsuda-4', 'en', 'He has got to the point of forgetting his promises.', 'authored'),
  ('st-ex-tatokorode-1', 'sent-ex-tatokorode-1', 'en', 'Hurrying will not get me there in time.', 'authored'),
  ('st-ex-tatokorode-2', 'sent-ex-tatokorode-2', 'en', 'Apologising will not get me forgiven.', 'authored'),
  ('st-ex-tatokorode-3', 'sent-ex-tatokorode-3', 'en', 'Saying it will change nothing.', 'authored'),
  ('st-ex-tatokorode-4', 'sent-ex-tatokorode-4', 'en', 'Even if I studied, I would probably not pass.', 'authored')
